import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.function.Function;

public class IoFunctionComposition {
    public static void main(String[] args) {
        Function<String, byte[]> toBytes = s -> s.getBytes(StandardCharsets.UTF_8);
        Function<byte[], String> base64Encode = b -> Base64.getEncoder().encodeToString(b);
        Function<String, String, String> prependHeader = header -> (String data) -> header + ": " + data;

        // Using andThen to chain transformation: String -> bytes -> Base64 string
        Function<String, String> securePipeline = toBytes.andThen(base64Encode);

        // Using compose: applies base64 encoding before prepending the header
        Function<String, String> finalPipeline = prependHeader.apply("AUTH").compose(securePipeline);

        String result = finalPipeline.apply("secret-payload");
        System.out.println(result);
    }
}
